The swap scoring logic (`+3 pantry bonus`, `+1 category match`, macro distance) has no handler test.

```typescript
// apps/lambdas/grocery-lambda/__tests__/suggestSwaps.test.ts

describe('POST /grocery/items/:id/suggest-swaps', () => {
  it('returns 200 with ranked suggestions (pantry items score higher)', async () => {
    // First select: verify item ownership + get ingredientId
    // Second select: candidate substitutes from ingredients
    // Third select: pantry lookup → Oats is in pantry
    vi.mocked(db.select)
      .mockReturnValueOnce(mockChain([{ id: ITEM_ID, ingredientId: 'oats-id', groceryListId: LIST_ID }]))
      .mockReturnValueOnce(mockChain([
        { id: 'quinoa-id', name: 'Quinoa', category: 'grains', ... },
        { id: 'oats-id',  name: 'Oats',   category: 'grains', ... },
      ]))
      .mockReturnValueOnce(mockChain([{ ingredientId: 'oats-id' }])) // oats in pantry

    const result = await handler(mockEvent({
      httpMethod: 'POST', path: `/grocery/items/${ITEM_ID}/suggest-swaps`,
      pathParameters: { id: ITEM_ID }
    }))
    expect(result.statusCode).toBe(200)
    const body = JSON.parse(result.body)
    // Oats should rank first due to pantry bonus (+3)
    expect(body.data[0].inPantry).toBe(true)
    expect(body.data.length).toBeLessThanOrEqual(3)
