  it('returns empty array for manual items (no ingredientId)', async () => {
    vi.mocked(db.select).mockReturnValueOnce(mockChain([{ id: ITEM_ID, ingredientId: null }]))
    const result = await handler(mockEvent({
      httpMethod: 'POST', path: `/grocery/items/${ITEM_ID}/suggest-swaps`,
      pathParameters: { id: ITEM_ID }
    }))
    expect(result.statusCode).toBe(200)
    expect(JSON.parse(result.body).data).toEqual([])
  })

  it('returns 404 when item belongs to another user', async () => {
    vi.mocked(db.select).mockReturnValueOnce(mockChain([]))
    const result = await handler(mockEvent({
      httpMethod: 'POST', path: `/grocery/items/${ITEM_ID}/suggest-swaps`,
      pathParameters: { id: ITEM_ID }
