`POST /supplements/skip-today` has no test in `handler.test.ts`. The inventory auto-decrement on `taken=true` is also untested through the handler.

```typescript
// Append to apps/lambdas/supplements-lambda/__tests__/handler.test.ts

describe('POST /supplements/skip-today', () => {
  it('returns 200 and inserts skip rows for all active supplements', async () => {
    const activeSupps = [
      { id: 'us-1', userId: 'user-123', isActive: true },
      { id: 'us-2', userId: 'user-123', isActive: true },
    ]
    mockDb.select.mockReturnValue(makeChain(activeSupps))
    mockDb.insert.mockReturnValue(makeInsertChain([]))

    const result = await handler(mockEvent({
      httpMethod: 'POST', path: '/supplements/skip-today'
    }))
    expect(result.statusCode).toBe(200)
    const body = JSON.parse(result.body)
    expect(body.data.skipped).toBe(2)
  })

  it('is idempotent — second call same day returns same count without duplicate rows', async () => {
    // ON CONFLICT DO NOTHING means insert is called but rows skipped at DB level
    mockDb.select.mockReturnValue(makeChain([{ id: 'us-1', userId: 'user-123' }]))
    mockDb.insert.mockReturnValue(makeInsertChain([]))

    await handler(mockEvent({ httpMethod: 'POST', path: '/supplements/skip-today' }))
    const result = await handler(mockEvent({ httpMethod: 'POST', path: '/supplements/skip-today' }))
    expect(result.statusCode).toBe(200)
  })

  it('returns 200 with skipped=0 when user has no active supplements', async () => {
    mockDb.select.mockReturnValue(makeChain([]))
    const result = await handler(mockEvent({
      httpMethod: 'POST', path: '/supplements/skip-today'
    }))
    expect(result.statusCode).toBe(200)
    expect(JSON.parse(result.body).data.skipped).toBe(0)
  })

  it('returns 401 without auth', async () => { /* ... */ })
})

describe('POST /supplements/log — inventory auto-decrement (Tier K)', () => {
  it('decrements inventory when taken=true', async () => {
    mockDb.select.mockReturnValue(makeChain([
      { id: 'us-1', userId: 'user-123', doseAmount: '5', scheduledTimes: [] }
    ]))
    mockDb.insert.mockReturnValue(makeInsertChain([{ id: 'log-1', taken: true }]))
    mockDb.update.mockReturnValue(makeUpdateChain([{ id: 'inv-1', quantityRemaining: '55' }]))

    const result = await handler(mockEvent({
      httpMethod: 'POST', path: '/supplements/log',
      body: JSON.stringify({ userSupplementId: 'us-1', logDate: '2026-03-27', taken: true })
    }))
    expect(result.statusCode).toBe(200)
    // db.update should be called to decrement inventory
    expect(mockDb.update).toHaveBeenCalled()
  })

  it('does NOT decrement inventory when taken=false', async () => {
    mockDb.select.mockReturnValue(makeChain([
      { id: 'us-1', userId: 'user-123', doseAmount: '5', scheduledTimes: [] }
    ]))
    mockDb.insert.mockReturnValue(makeInsertChain([{ id: 'log-1', taken: false }]))

    const result = await handler(mockEvent({
      httpMethod: 'POST', path: '/supplements/log',
      body: JSON.stringify({ userSupplementId: 'us-1', logDate: '2026-03-27', taken: false })
    }))
    expect(result.statusCode).toBe(200)
    // db.update should NOT be called (no decrement for skipped doses)
    expect(mockDb.update).not.toHaveBeenCalled()
  })

  it('gracefully continues when inventory row does not exist (silent no-op)', async () => {
    mockDb.select.mockReturnValue(makeChain([
      { id: 'us-1', userId: 'user-123', doseAmount: '5', scheduledTimes: [] }
    ]))
    mockDb.insert.mockReturnValue(makeInsertChain([{ id: 'log-1', taken: true }]))
    // inventory update returns empty (no row to decrement)
    mockDb.update.mockReturnValue(makeUpdateChain([]))

    const result = await handler(mockEvent({
      httpMethod: 'POST', path: '/supplements/log',
      body: JSON.stringify({ userSupplementId: 'us-1', logDate: '2026-03-27', taken: true })
    }))
    // Should still return 200 — missing inventory is a no-op not an error
    expect(result.statusCode).toBe(200)
  })
})
