import { render, screen, fireEvent } from '@testing-library/react'
import { SetRow } from '../SetRow'

describe('SetRow', () => {
  const mockSet = { id: 's1', reps: 8, weight: 80, rpe: 7, isCompleted: false }

  it('renders reps, weight, and RPE', () => {
    render(<SetRow set={mockSet} onUpdate={vi.fn()} />)
    expect(screen.getByDisplayValue('8')).toBeInTheDocument()
    expect(screen.getByDisplayValue('80')).toBeInTheDocument()
  })

  it('calls onUpdate when weight is changed', () => {
    const onUpdate = vi.fn()
    render(<SetRow set={mockSet} onUpdate={onUpdate} />)
    fireEvent.change(screen.getByLabelText(/weight/i), { target: { value: '85' } })
    expect(onUpdate).toHaveBeenCalledWith(expect.objectContaining({ weight: 85 }))
  })

  it('rejects RPE above 10', () => {
    render(<SetRow set={mockSet} onUpdate={vi.fn()} />)
    const rpeInput = screen.getByLabelText(/rpe/i)
    fireEvent.change(rpeInput, { target: { value: '11' } })
    expect(screen.getByText(/RPE must be/i)).toBeInTheDocument()
  })
})
